    "C43","C45","C47","C50","C53","C55","C60","C70","C74","C75","C78","C80","C81","C82"
  ],
  "claims": [
    {
      "claim": "The query is talinolol, an aryloxypropanolamine beta-blocker with a tert-butylamino group and a para-cyclohexylurea; the closest visible beta-blocker contexts report direct absolute oral F values all at or above 27% (CP-331,684 27%; diacetolol 30-43%; celiprolol 30-70%; almokalant ~50%; betaxolol 80-89%; practolol ~100%; pamatolol 64.9-150.5%).",
      "card_ids": ["C16","C01","C02","C03","C07","C08","C09","C19","C05","C22","C23","C31","C34","C38"]
    },
    {
      "claim": "L2 records add further human F/RBA values >=30% for the same beta-blocker contexts (betaxolol 80-89%, celiprolol 50-74%, pamatolol 90-150%, diacetolol 30-42%, practolol ~100%, CP-331,684 oral solution RBA 100%), reinforcing class-level support for F >= 20%.",
      "card_ids": ["C43","C45","C47","C50","C53","C55","C60","C70","C74","C75","C78","C80","C81","C82"]
    },
    {
      "claim": "L3 oral exposure records for beta-blockers (nadolol, atenolol, metoprolol, pindolol) show measurable oral AUC/Cmax in humans, consistent with oral absorption; interaction records show reduced but still measurable exposure with other modifiers, and none involve rifampin or the query.",
      "card_ids": ["C85","C98","C101","C102","C103","C112","C114","C123","C127","C84","C87","C89","C94","C110"]
    },
    {
      "claim": "No visible card reports a direct F < 20% outcome for the query under rifampin; the only sub-20% absolute F records are rat data for CP-409,092 with low transferability, and the celiprolol grapefruit-juice/intestinal-secretion records involve a different molecule and modifier.",
      "card_ids": ["C61","C64","C66","C71","C42","C56"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "low",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C84","C85","C87","C89","C94","C98","C101","C102","C103","C105","C110","C112","C114","C123","C127","C131"]
    }
  ],
  "evidence_gaps": [
    "No direct talinolol absolute oral bioavailability measurement under rifampin co-treatment is present in the visible records.",
    "No L3 record involves talinolol or rifampin; the magnitude of rifampin-mediated P-gp/CYP induction on this exact molecule is unquantified.",
    "The L3 exposure records provide AUC/Cmax but not F values, so they cannot directly confirm the F >= 20% threshold.",
    "No experimental solubility or permeability data for the query are supplied.",
    "Repeated records from the same parent context are not independent votes."
  ],
  "decision_summary": "The query is talinolol, a beta-blocker structurally aligned with contexts whose direct absolute oral F values are all >=27%; L3 adds only other-molecule oral exposure records and no direct rifampin/talinolol data, so no affirmative evidence supports F < 20% and the positive class remains better supported."
}

